{"code": "// Transpose every phrase of the score so that one chosen note of it lands on a target pitch.
// The pivot is per phrase (first, last, highest, lowest, or a fixed index); if the requested
// index is out of range for a phrase, the last note of that phrase is used instead.

const params = {
  pivot:   { type: "menu", options: ["first", "last", "highest", "lowest", "nth"], value: "first" },
  index:   { type: "slider", range: [1, 24], value: 3 },
  target:  { type: "slider", range: [1200, 12700], value: 6400, unit: "mc" },
  gap:     { type: "slider", range: [50, 2000], value: 400, unit: "ms" },
};

function transform(source, p) {
  const out = copy(source);

  // Pick the pivot note of one phrase (a list of chords).
  function pivotOf(phrase) {
    const n = phrase.length;
    if (n === 0) return null;
    let idx;
    if (p.pivot === "first") idx = 0;
    else if (p.pivot === "last") idx = n - 1;
    else if (p.pivot === "highest") {
      let best = 0, bp = -Infinity;
      for (let i = 0; i < n; i++) {
        const top = Math.max(...phrase[i].notes.map((x) => x.pitch));
        if (top > bp) { bp = top; best = i; }
      }
      idx = best;
    } else if (p.pivot === "lowest") {
      let best = 0, bp = Infinity;
      for (let i = 0; i < n; i++) {
        const bot = Math.min(...phrase[i].notes.map((x) => x.pitch));
        if (bot < bp) { bp = bot; best = i; }
      }
      idx = best;
    } else { // "nth": 1-based note number, falls back to the last note if out of range
      idx = clamp(p.index - 1, 0, n - 1);
    }
    return phrase[idx].notes[0]; // the pivot is one note of the phrase
  }

  for (const voice of out.voices) {
    const parts = phrases(voice, p.gap);
    for (const phrase of parts) {
      const piv = pivotOf(phrase);
      if (!piv) continue;
      const shift = p.target - piv.pitch;
      for (const chord of phrase) {
        for (const note of chord.notes) {
          note.pitch = Math.round(note.pitch + shift);
        }
      }
    }
  }
  return out;
}
